messages.content:
Write the application service of PayOrder.

Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": "amount",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKeyForUpdate",
     "description": "Reads the order by order number and company and locks the row (READ FILE ORDENES UPDATE). Empty when it does not exist (NOTFND).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Rewrites the order as paid with its movement number and commission (REWRITE FILE ORDENES).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "status",
       "type": "text(fixed,1,iso8859-1)",
       "column": null,
       "legacy": "ORD_ESTADO"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberForUpdate",
     "description": "Reads the account by number and locks the row (READ FILE CUENTAS UPDATE). Empty when it does not exist (NOTFND).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Rewrites the account with its new balance (REWRITE FILE CUENTAS).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "DebitGateway",
   "entity": null,
   "legacy_program": null,
   "methods": [
    {
     "name": "debit",
     "description": "Debits an account (replaces the LINK from PAGOORD to PAGODEB). Implemented in-process by the DebitAccount use case inside the caller's transaction. Returns the legacy DEB-RESP as a number: 0 debited, 10 inactive, 20 insufficient balance, 30 not found, 40 type mismatch.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "DEB_CUENTA"
      },
      {
       "name": "accountType",
       "type": "text(fixed,3,iso8859-1)",
       "column": null,
       "legacy": "DEB_TIPO"
      },
      {
       "name": "amount",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "DEB_MONTO"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the payment movement for an order and returns the movement number (LINK to PAGOMOV, whose source is not available: stubbed).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "PayOrder",
   "description": "Validates the request, reads the pending order, checks the amount, calculates the commission, debits the account, registers the movement and marks the order as paid. Stops at the first error.",
   "rules": [
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015",
    "RULE-016",
    "RULE-017"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyId",
     "type": "text(fixed,5,iso8859-1)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "accountNumber",
     "type": "text(fixed,10,iso8859-1)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(var,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "message",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "HAY-ERROR",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "HAY-ERROR",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "HAY-ERROR",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "HAY-ERROR",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "HAY-ERROR",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "HAY-ERROR",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "HAY-ERROR",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_BALANCE",
     "legacy_code": "20",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "INVALID_ACCOUNT",
     "legacy_code": "OTHER",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "DebitGateway",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/payments/orders/pay",
   "legacy_program": "PAGOORD",
   "legacy_message": "MENSAJE"
  },
  {
   "name": "DebitAccount",
   "description": "Debits an account: it must exist, have the requested type, be active and have enough balance (a debit equal to the balance is accepted). Then it reduces the balance.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005"
   ],
   "inputs": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "DEB_CUENTA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "DEB_TIPO"
    },
    {
     "name": "amount",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "DEB_MONTO"
    }
   ],
   "outputs": [
    {
     "name": "newBalance",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "CTA_SALDO"
    },
    {
     "name": "responseCode",
     "type": "text(fixed,2,iso8859-1)",
     "column": null,
     "legacy": "DEB_RESP"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_NOT_FOUND",
     "legacy_code": "30",
     "message": "CUENTA NO EXISTE"
    },
    {
     "code": "ACCOUNT_TYPE_MISMATCH",
     "legacy_code": "40",
     "message": "EL TIPO DE CUENTA NO COINCIDE"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_BALANCE",
     "legacy_code": "20",
     "message": "SALDO INSUFICIENTE"
    }
   ],
   "ports": [
    "AccountRepository"
   ],
   "http_method": "POST",
   "path": "/accounts/debits",
   "legacy_program": "PAGODEB",
   "legacy_message": "DEB_RESP"
  },
  {
   "name": "SelectMenuOption",
   "description": "Interprets the payments menu option: '1' opens payment of orders, '9' ends the session, any other option is rejected.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "action",
     "type": "text(var,10,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    },
    {
     "name": "message",
     "type": "text(var,78,iso8859-1)",
     "column": null,
     "legacy": "MENSAJEO"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "OTHER",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/payments/menu/options",
   "legacy_program": "PAGOMNU",
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "One transaction per payment replaces SYNCPOINT",
   "context": "PAGOORD debits the account (PAGODEB), links PAGOMOV, rewrites the order and only then issues SYNCPOINT.",
   "decision": "PayOrder runs in a single database transaction. DebitAccount joins it when called through DebitGateway. Any business error or exception rolls back everything.",
   "consequences": "The debit, the movement registration and the order update are atomic. The legacy SYNCPOINT disappears."
  },
  {
   "title": "Pessimistic locking replaces READ ... UPDATE",
   "context": "The legacy reads ORDENES and CUENTAS with UPDATE, which holds the record until the task ends.",
   "decision": "findByKeyForUpdate and findByNumberForUpdate use SELECT ... FOR UPDATE, in the legacy order (order first, then account).",
   "consequences": "Concurrent payments of the same order or debits of the same account are serialized, as before."
  },
  {
   "title": "PAGODEB becomes a use case called in-process through DebitGateway",
   "context": "PAGOORD calls PAGODEB with LINK and a COMMAREA. PAGODEB answers with a response code (00, 10, 20, 30, 40).",
   "decision": "The debit logic lives only in the DebitAccount use case, also exposed as POST /accounts/debits. PayOrder reaches it through DebitGateway and receives the legacy code as a number. It maps 10 to ACCOUNT_INACTIVE, 20 to INSUFFICIENT_BALANCE and any other code (30, 40) to INVALID_ACCOUNT.",
   "consequences": "No duplicated rules. PAGODEB runs for real in the recorded traces, so the port has no legacy_program and is not stubbed in the replay. The effect of the debit is checked in the CUENTAS table."
  },
  {
   "title": "PAGOMOV is stubbed",
   "context": "The source of PAGOMOV is not available.",
   "decision": "MovementGateway is a port with a stub adapter. The replay uses the stubs recorded in the traces.",
   "consequences": "The real movement numbering must be implemented or integrated before going live."
  },
  {
   "title": "Amount is received in currency units",
   "context": "The legacy screen sends VALORI as 11 digits and PAGOORD converts it with NUMVAL / 100. The traces give the value as '1500.00'.",
   "decision": "The API receives amount as decimal(11,2). The comparison with the order amount is exact (scale 2, compareTo), with no rounding.",
   "consequences": "The client sends 1500.00 instead of the screen format. Any difference of one cent rejects the payment, as before."
  },
  {
   "title": "Identifiers are received as text and validated inside the use case",
   "context": "ORDENI, EMPRESAI and CUENTAI are alphanumeric on the screen and RULE-008 rejects a non-numeric or zero order number.",
   "decision": "orderNumber, companyId and accountNumber are text in PayOrder. A non-numeric or zero order number gives INVALID_ORDER_NUMBER. A non-numeric company gives ORDER_NOT_FOUND. A non-numeric account gives INVALID_ACCOUNT.",
   "consequences": "The last two are interpretations of the legacy behaviour for a non-numeric key. Screen checks (PF keys, TECLA NO VALIDA, BMS maps) are not migrated."
  },
  {
   "title": "Validation order and short circuit",
   "context": "RULE-007: validation, read, commission and debit, registration.",
   "decision": "PayOrder validates in the legacy order (order number, account type, channel, approval key), then reads the order (exists, pending, amount), calculates the commission, debits and registers. The first error ends the use case.",
   "consequences": "Only one error message is reported per request, as in the legacy."
  },
  {
   "title": "Commarea state is not persisted",
   "context": "The pseudo-conversational commarea carries state between screens. RULE-017 sets CA-ULTIMA-ORDEN.",
   "decision": "The service is stateless. The paid order number is returned as orderNumber. The menu navigation (XCTL) is the action returned by SelectMenuOption.",
   "consequences": "The client keeps any session context."
  },
  {
   "title": "Legacy status codes kept",
   "context": "Orders use 'P' (pending) and 'G' (paid). Accounts use 'A' (active) and 'I' (inactive).",
   "decision": "The values are kept in the new tables. Columns are renamed to English snake_case and FILLER is not migrated.",
   "consequences": "Data migrates without conversion."
  }
 ],
 "masks": [],
 "infrastructure": []
}

Rules:
[
 {
  "id": "RULE-007",
  "name": "Payment processing sequence stops at first failure",
  "category": "policy",
  "priority": "P0",
  "statement": "Input validation runs first; the order is read only if validation left no error. Commission calculation and account debit run together, in that order, only if no error exists after the order read. There is no error check between commission and debit. Registration of the payment and the result screen happen only if no error remains after the debit; otherwise the error screen (8000-ENVIAR-ERROR) is sent.",
  "condition": "Validate input; if OK read the order; if OK calculate commission and debit; if still OK register the payment, otherwise send the error",
  "action": "Run the steps in order and stop at the first error. Registration and the result screen happen only without errors. Otherwise the error screen is sent.",
  "inputs": [
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Validation failure prevents debit\n Given channel 'ATM'\n When the user presses ENTER\n Then the order is not read, no debit is made and 'CANAL NO PERMITIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 66,
    "line_end": 80
   }
  ]
 },
 {
  "id": "RULE-008",
  "name": "Order number must be numeric and non-zero",
  "category": "validation",
  "priority": "P1",
  "statement": "If the order number ORDENI is not numeric or equals zeros, the message 'NUMERO DE ORDEN INVALIDO' is placed in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "ORDENI is not numeric OR ORDENI = ZEROS",
  "action": "Set the message 'NUMERO DE ORDEN INVALIDO' and flag the request as in error. No order is read and no debit is made.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Non-numeric order number\n Given the order number entered is '12A4567'\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown and the payment is not processed",
   "Scenario: Zero order number\n Given the order number entered is '0000000'\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 83,
    "line_end": 85
   }
  ]
 },
 {
  "id": "RULE-009",
  "name": "Allowed account types for payment",
  "category": "validation",
  "priority": "P0",
  "statement": "If TIPCTAI is not 'CTE', 'AHO' or 'VIR', the message 'TIPO DE CUENTA NO PERMITIDO' is moved to WS-MENSAJE and HAY-ERROR is set.",
  "condition": "TIPCTAI NOT = 'CTE' AND TIPCTAI NOT = 'AHO' AND TIPCTAI NOT = 'VIR' (evaluated only when the order number is valid)",
  "action": "Set the message 'TIPO DE CUENTA NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "TIPCTAI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type not allowed\n Given a valid order number and account type 'PLZ'\n When the user presses ENTER\n Then the message 'TIPO DE CUENTA NO PERMITIDO' is shown",
   "Scenario: Account type allowed\n Given a valid order number and account type 'AHO'\n When the request is validated\n Then the account type check passes"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 87,
    "line_end": 90
   }
  ]
 },
 {
  "id": "RULE-010",
  "name": "Allowed channels for payment",
  "category": "validation",
  "priority": "P1",
  "statement": "Payments are accepted only through channel WEB or OFI. If CANALI is neither 'WEB' nor 'OFI', the message 'CANAL NO PERMITIDO' is set and the request is flagged as in error (HAY-ERROR).",
  "condition": "CANALI NOT = 'WEB' AND CANALI NOT = 'OFI' (evaluated only when the order number and account type are valid)",
  "action": "Set the message 'CANAL NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Invalid channel\n Given a valid order number, account type 'CTE' and channel 'ATM'\n When the user presses ENTER\n Then the message 'CANAL NO PERMITIDO' is shown",
   "Scenario: Valid channel\n Given channel 'WEB'\n When the request is validated\n Then the channel check passes"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 92,
    "line_end": 94
   }
  ]
 },
 {
  "id": "RULE-011",
  "name": "Approval key required for office channel",
  "category": "validation",
  "priority": "P1",
  "statement": "A payment made through the office channel (OFI) must include an approval key. If the key is blank the request is rejected with 'CLAVE DE APROBACION REQUERIDA'.",
  "condition": "CANALI = 'OFI' AND CLAVEI = SPACES",
  "action": "Set the message 'CLAVE DE APROBACION REQUERIDA' and flag the request as in error.",
