package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.PaymentOrder;
import com.bank.payments.domain.port.DebitGateway;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Application service of the PayOrder use case (legacy program PAGOORD). */
public class PayOrderService {

    private static final String HAY_ERROR = "HAY-ERROR";
    private static final BigDecimal COMMISSION_THRESHOLD = new BigDecimal("50000");
    private static final BigDecimal COMMISSION_WEB = new BigDecimal("1.00");
    private static final BigDecimal COMMISSION_OFFICE = new BigDecimal("2.50");

    private final OrderRepository orderRepository;
    private final DebitGateway debitGateway;
    private final MovementGateway movementGateway;

    public PayOrderService(OrderRepository orderRepository, DebitGateway debitGateway,
                           MovementGateway movementGateway) {
        this.orderRepository = orderRepository;
        this.debitGateway = debitGateway;
        this.movementGateway = movementGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // RULE-008: order number numeric and non-zero
        Integer orderNumber = parseDigits(request.orderNumber(), Integer.class);
        if (orderNumber == null || orderNumber == 0) {
            throw new BusinessError("INVALID_ORDER_NUMBER", HAY_ERROR, "NUMERO DE ORDEN INVALIDO");
        }

        // RULE-009: account type
        String accountType = request.accountType();
        if (!"CTE".equals(accountType) && !"AHO".equals(accountType) && !"VIR".equals(accountType)) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", HAY_ERROR, "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-010: channel
        String channel = request.channel();
        if (!"WEB".equals(channel) && !"OFI".equals(channel)) {
            throw new BusinessError("CHANNEL_NOT_ALLOWED", HAY_ERROR, "CANAL NO PERMITIDO");
        }

        // RULE-011: approval key for office channel
        if ("OFI".equals(channel) && (request.approvalKey() == null || request.approvalKey().isBlank())) {
            throw new BusinessError("APPROVAL_KEY_REQUIRED", HAY_ERROR, "CLAVE DE APROBACION REQUERIDA");
        }

        // RULE-012: order must exist
        Integer companyId = parseDigits(request.companyId(), Integer.class);
        if (companyId == null) {
            throw new BusinessError("ORDER_NOT_FOUND", HAY_ERROR, "ORDEN NO EXISTE");
        }
        Optional<PaymentOrder> found = orderRepository.findByKeyForUpdate(orderNumber, companyId);
        if (found.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", HAY_ERROR, "ORDEN NO EXISTE");
        }
        PaymentOrder order = found.get();

        // RULE-013: only pending
        if (!"P".equals(order.status())) {
            throw new BusinessError("ORDER_NOT_PENDING", HAY_ERROR, "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-014: amount must match exactly
        if (request.amount() == null || order.amount() == null
                || request.amount().compareTo(order.amount()) != 0) {
            throw new BusinessError("AMOUNT_MISMATCH", HAY_ERROR, "VALOR NO COINCIDE CON LA ORDEN");
        }

        // RULE-015: commission and total
        BigDecimal commission;
        if (order.amount().compareTo(COMMISSION_THRESHOLD) >= 0) {
            commission = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_UP);
        } else if ("WEB".equals(channel)) {
            commission = COMMISSION_WEB;
        } else {
            commission = COMMISSION_OFFICE;
        }
        BigDecimal total = order.amount().add(commission).setScale(2, RoundingMode.HALF_UP);

        // RULE-016: debit
        Long accountNumber = parseDigits(request.accountNumber(), Long.class);
        if (accountNumber == null) {
            throw new BusinessError("INVALID_ACCOUNT", "OTHER", "CUENTA NO VALIDA");
        }
        int response = debitGateway.debit(accountNumber, accountType, total);
        if (response == 10) {
            throw new BusinessError("ACCOUNT_INACTIVE", "10", "CUENTA INACTIVA");
        } else if (response == 20) {
            throw new BusinessError("INSUFFICIENT_BALANCE", "20", "SALDO INSUFICIENTE");
        } else if (response != 0) {
            throw new BusinessError("INVALID_ACCOUNT", "OTHER", "CUENTA NO VALIDA");
        }

        // RULE-017: register movement and mark order paid
        long movementNumber = movementGateway.registerMovement(order.orderNumber());
        orderRepository.markPaid(order.orderNumber(), order.companyId(), "G", movementNumber, commission);

        return new PayOrderResponse(String.format("%07d", order.orderNumber()), commission,
                movementNumber, "PAGO REALIZADO");
    }

    /** Returns the numeric value when the text is only digits (COBOL NUMERIC), null otherwise. */
    @SuppressWarnings("unchecked")
    private static <T extends Number> T parseDigits(String text, Class<T> type) {
        if (text == null || text.isEmpty()) {
            return null;
        }
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c < '0' || c > '9') {
                return null;
            }
        }
        try {
            if (type == Integer.class) {
                return (T) Integer.valueOf(Integer.parseInt(text));
            }
            return (T) Long.valueOf(Long.parseLong(text));
        } catch (NumberFormatException e) {
            return null;
        }
    }
}
